class Cart:
    def __init__(self):
        self.items = []

    def add(self, name, price, qty=1):
        self.items.append({"name": name, "price": price, "qty": qty})

    @property
    def total(self):
        return sum(i["price"] * i["qty"] for i in self.items)

    def most_expensive(self):
        best = max(self.items, key=lambda i: i["price"] * i["qty"])
        return best["name"]

cart = Cart()
cart.add("pen", 1.5, 4)
cart.add("book", 12.0)
cart.add("bag", 6.0, 2)
print(f"{cart.total:.2f}")
print(cart.most_expensive())

class Thermometer:
    def __init__(self, celsius):
        self.celsius = celsius

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        if value < -273.15:
            raise ValueError("below absolute zero")
        self._celsius = value

    @property
    def fahrenheit(self):
        return self._celsius * 9 / 5 + 32

t = Thermometer(25)
print(t.fahrenheit)
t.celsius = 100
print(t.fahrenheit)
try:
    t.celsius = -300
except ValueError as error:
    print(error)
print(t.celsius)

class Warehouse:
    count = 0

    def __init__(self, name):
        self.name = name
        self.stock = {}
        Warehouse.count += 1

    def receive(self, sku, n):
        self.stock[sku] = self.stock.get(sku, 0) + n

    def ship(self, sku, n):
        if self.stock.get(sku, 0) < n:
            raise ValueError("insufficient stock")
        self.stock[sku] -= n

    def __repr__(self):
        return f"Warehouse({self.name}, {sum(self.stock.values())} units)"

north = Warehouse("north")
south = Warehouse("south")
north.receive("A", 10)
north.receive("B", 5)
south.receive("A", 3)
north.ship("A", 4)
try:
    north.ship("B", 9)
except ValueError as error:
    print(error)
print(north)
print(south)
print(Warehouse.count)
